const m = $input.first().json.message;
if (!m || m.chat?.type !== 'private') return [];
// CONFIGURACIÓN OBLIGATORIA: colocá tu propio chat_id numérico.
// No publiques tu chat_id personal en GitHub.
const CHAT_PERMITIDO = 'YOUR_TELEGRAM_CHAT_ID';
const chatId = String(m.chat.id);
if (chatId !== CHAT_PERMITIDO) return [];
const texto = String(m.text || '').trim().toLocaleLowerCase('es').replace(/\s+/g, ' ');
let evento = '';
if (texto === 'iniciar ciclo de generación') evento = 'iniciar';
else if (texto === 'reiniciar ciclo') evento = 'reiniciar';
else if (Array.isArray(m.photo) && m.photo.length > 0 && !m.media_group_id) evento = 'foto';
if (!evento) return [];
const fileId = evento === 'foto' ? m.photo[m.photo.length - 1].file_id : '';
return [{ json: {
  chat_id: chatId,
  evento,
  file_id: fileId,
  caption: String(m.caption || '').trim(),
  mensaje_id: String(m.message_id || ''),
} }];

const ev = $('Normalizar entrada').first().json;
const fila = $input.first()?.json || {};
const row = {
  chat_id: fila.chat_id,
  estado: fila.Estado ?? fila.estado,
  cantidad: fila.Cantidad ?? fila.cantidad,
  productos_json: fila.Productos_Json ?? fila.productos_json,
  ciclo_id: fila.Ciclo_id ?? fila.ciclo_id,
};
const actual = row.chat_id && String(row.chat_id) === ev.chat_id ? row : {};
let productos;
try { productos = JSON.parse(actual.productos_json || '[]'); } catch { productos = []; }
if (!Array.isArray(productos)) productos = [];
const activo = actual.estado === 'recibiendo';
const resultado = (modo, respuesta, extra = {}) => [{json: {
  modo, respuesta, chat_id: ev.chat_id,
  estado: extra.estado || actual.estado || '',
  cantidad: extra.cantidad ?? productos.length,
  productos_json: extra.productos_json || JSON.stringify(productos),
  ciclo_id: extra.ciclo_id || actual.ciclo_id || '',
  finalizado: Boolean(extra.finalizado),
}}];
const formato = 'Nombre: Nombre del producto\nID: CODIGO-OFICIAL';
if (ev.evento === 'iniciar') {
  // Si el ciclo ya tiene 9 productos, este mismo comando vuelve a lanzar la IA
  // sin perder las fotografías/IDs guardados.
  if (actual.estado === 'preparado' && productos.length === 9) {
    return resultado('guardar',
      '🎨 Reanudando generación con los 9 productos ya guardados. No tenés que enviarlos de nuevo.',
      {estado:'preparado', cantidad:9, productos_json:JSON.stringify(productos), finalizado:true});
  }
  if (activo) return resultado('aviso', `Ya hay un ciclo activo. Enviá la foto del producto ${productos.length + 1}. Si querés empezar desde cero, escribí: reiniciar ciclo`);
  const ciclo = `${Date.now()}-${ev.chat_id}`;
  return resultado('guardar', `✅ Ciclo iniciado.\n\nEnviá UNA foto del producto 1 con este pie de foto:\n\n${formato}`, {estado:'recibiendo', cantidad:0, productos_json:'[]', ciclo_id:ciclo});
}
if (ev.evento === 'reiniciar') {
  const ciclo = `${Date.now()}-${ev.chat_id}`;
  return resultado('guardar', `🔄 Ciclo reiniciado.\n\nEnviá UNA foto del producto 1 con este pie de foto:\n\n${formato}`, {estado:'recibiendo', cantidad:0, productos_json:'[]', ciclo_id:ciclo});
}
if (ev.evento !== 'foto' || !activo || productos.length >= 9) return [];
if (productos.some(p => String(p.mensaje_id) === ev.mensaje_id)) return [];
const caption = ev.caption.replace(/\r\n/g, '\n');
const valor = (campo) => {
  const re = new RegExp(`^\\s*${campo}\\s*:\\s*(.+?)\\s*$`, 'im');
  return (caption.match(re)?.[1] || '').trim();
};
const nombre = valor('Nombre');
const id = valor('ID');
if (!nombre || !id) return resultado('aviso', `❌ Falta el nombre o ID del producto ${productos.length + 1}.\nReenviá UNA foto con este pie de foto:\n\n${formato}`);
const indice = productos.length + 1;
productos.push({
  indice, nombre, id,
  file_id: ev.file_id,
  mensaje_id: ev.mensaje_id,
  precio: valor('Precio'),
  precio_anterior: valor('Precio anterior'),
  descuento: valor('Descuento'),
});
const finalizado = indice === 9;
const respuesta = finalizado
  ? '✅ Guardé los 9 productos con sus IDs.\nIniciando el procesamiento de los 9 productos con Cloudflare. Si Cloudflare bloquea una foto, se conservará la original como respaldo. En caso de error técnico, escribí iniciar ciclo de generación para reintentar sin recargar fotos.'
  : `✅ Producto ${indice}/9 guardado: ${nombre} (${id}).\n\nAhora enviá UNA foto del producto ${indice + 1} con:\n\n${formato}`;
return resultado('guardar', respuesta, {
  estado: finalizado ? 'preparado' : 'recibiendo',
  cantidad: productos.length,
  productos_json: JSON.stringify(productos),
  finalizado,
});

const actual = $('Gestionar ciclo y productos').first().json;
if (!actual.finalizado) return [];
const productos = JSON.parse(actual.productos_json || '[]');
if (productos.length !== 9) throw new Error('Se esperaban 9 productos.');
const descripcion = productos.map(p => `${p.indice}. ${p.nombre}\nID: ${p.id}`).join('\n\n');
return productos.map(p => ({json: {
  chat_id: actual.chat_id,
  ciclo_id: actual.ciclo_id,
  orden: p.indice,
  nombre: p.nombre,
  id: p.id,
  file_id: p.file_id,
  precio: p.precio,
  precio_anterior: p.precio_anterior,
  descuento: p.descuento,
  descripcion_total: descripcion,
}}));

const resultado = $input.first().json || {};
const producto = $('Vincular datos y foto').first(0, $runIndex)?.json;
if (!producto?.orden || !producto?.file_id) {
  throw new Error('No se pudieron recuperar los datos del producto para esta vuelta del bucle');
}
const contenido = resultado?.result?.image ?? resultado?.image;
if (typeof contenido === 'string' && contenido.length > 100) {
  const limpio = contenido.replace(/^data:image\/[a-zA-Z0-9+.-]+;base64,/, '').trim();
  const extension = limpio.startsWith('/9j/') ? 'jpg' : 'png';
  const mime = extension === 'jpg' ? 'image/jpeg' : 'image/png';
  const archivo = await this.helpers.prepareBinaryData(
    Buffer.from(limpio, 'base64'),
    `producto_${producto.orden}_portada.${extension}`,
    mime
  );
  return [{ json: { ...producto, fuente_portada: 'generada_ia' }, binary: { portada: archivo } }];
}
// n8n entrega el error 3030 como JSON porque el HTTP Request usa Continue (regular output).
const detalle = JSON.stringify(resultado);
if (!/(3030|output has been flagged|choose another prompt\s*\/\s*input image)/i.test(detalle)) {
  throw new Error('Cloudflare no produjo una imagen. No parece ser el bloqueo 3030: ' + detalle.slice(0, 700));
}
// Respaldar usando la foto ORIGNAL de Telegram (NO la miniatura de 500 px).
const original = $('Get a file').first(0, $runIndex)?.binary?.data;
if (!original) throw new Error('Bloqueo 3030 y no se pudo recuperar la foto original de Telegram');
return [{
  json: { ...producto, fuente_portada: 'respaldo_3030', aviso_portada: 'Imagen rechazada por Cloudflare; se usa foto original.' },
  binary: { portada: { ...original } },
}];

const resultado = $input.first().json || {};
const producto = $('Vincular datos y foto').first(0, $runIndex)?.json;
if (!producto?.orden || !producto?.file_id) {
  throw new Error('No se pudieron recuperar los datos del producto para esta vuelta del bucle');
}
const contenido = resultado?.result?.image ?? resultado?.image;
if (typeof contenido === 'string' && contenido.length > 100) {
  const limpio = contenido.replace(/^data:image\/[a-zA-Z0-9+.-]+;base64,/, '').trim();
  const extension = limpio.startsWith('/9j/') ? 'jpg' : 'png';
  const mime = extension === 'jpg' ? 'image/jpeg' : 'image/png';
  const archivo = await this.helpers.prepareBinaryData(
    Buffer.from(limpio, 'base64'),
    `producto_${producto.orden}_collage.${extension}`,
    mime
  );
  return [{ json: { ...producto, fuente_collage: 'generada_ia' }, binary: { collage: archivo } }];
}
// n8n entrega el error 3030 como JSON porque el HTTP Request usa Continue (regular output).
const detalle = JSON.stringify(resultado);
if (!/(3030|output has been flagged|choose another prompt\s*\/\s*input image)/i.test(detalle)) {
  throw new Error('Cloudflare no produjo una imagen. No parece ser el bloqueo 3030: ' + detalle.slice(0, 700));
}
// Respaldar usando la foto ORIGNAL de Telegram (NO la miniatura de 500 px).
const original = $('Get a file').first(0, $runIndex)?.binary?.data;
if (!original) throw new Error('Bloqueo 3030 y no se pudo recuperar la foto original de Telegram');
return [{
  json: { ...producto, fuente_collage: 'respaldo_3030', aviso_collage: 'Imagen rechazada por Cloudflare; se usa foto original.' },
  binary: { collage: { ...original } },
}];

const unido = $input.first();
if (!unido.binary?.portada || !unido.binary?.collage) {
  throw new Error('Merge no entregó las dos imágenes para este producto');
}
if (!unido.json?.orden || !unido.json?.chat_id) {
  throw new Error('Faltan los datos del producto después de Merge');
}
return [{ json: unido.json, binary: unido.binary }];

const productos = $input.all().sort((a, b) => a.json.orden - b.json.orden);
if (productos.length !== 9) {
  throw new Error(`Se esperaban 9 productos terminados, llegaron ${productos.length}`);
}
const envios=[];
for (const p of productos) {
  for (const tipo of ['portada','collage']) {
    const f = p.binary?.[tipo];
    if (!f) throw new Error(`Falta ${tipo} del producto ${p.json.orden}`);
    const fuente = p.json[tipo === 'portada' ? 'fuente_portada' : 'fuente_collage'];
    const respaldo = fuente === 'respaldo_3030';
    const comentario = respaldo
      ? tipo === 'collage'
        ? 'AVISO: la IA bloqueó el collage. Se adjunta la foto original como respaldo; NO representa cuatro perspectivas.'
        : 'AVISO: la IA bloqueó la foto profesional. Portada compuesta con la foto original.'
      : 'Imagen generada con Cloudflare.';
    envios.push({
      json: {
        chat_id: p.json.chat_id,
        orden: p.json.orden,
        nombre: p.json.nombre,
        id: p.json.id,
        tipo,
        fuente,
        respaldo,
        caption: `Producto ${p.json.orden} - ${tipo}\n${comentario}`,
      },
      binary: {
        data: {
          ...f,
          fileName: `producto_${p.json.orden}_${tipo}.png`,
          mimeType: 'image/png',
          fileExtension: 'png',
        }
      }
    });
  }
}
return envios;

const f = $input.first();
const producto = $('Preparar 9 solicitudes individuales IA').all()[ $runIndex ]?.json;
if (!producto) throw new Error(`Faltan los metadatos del producto ${$runIndex + 1}`);
if (!f.binary?.data) throw new Error('Telegram no proporcionó archivo binario');
return [{json:{...producto},binary:{data:f.binary.data}}];
